import { landscapeInputIssues } from "./landscapeMaterials";

const inputNumber = value => {
  if (typeof value === "number") return Number.isFinite(value) ? value : null;
  if (typeof value !== "string" || !/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)$/.test(value.trim())) return null;
  const number = Number(value);
  return Number.isFinite(number) ? number : null;
};

const positiveWholeNumber = value => {
  const number = inputNumber(value);
  const whole = typeof value !== "string" || /^[+-]?\d+(?:\.0*)?$/.test(value.trim());
  return whole && Number.isSafeInteger(number) && number > 0;
};

const ITEM_CUSTOM_OVERRIDE_FIELDS = [
  ["custom_concrete_cost_per_cy", "concrete cost-per-unit override"],
  ["custom_concrete_qty", "concrete quantity override"],
  ["custom_rebar_cost_per_ft", "rebar cost-per-foot override"],
  ["custom_rebar_qty", "rebar quantity override"],
  ["custom_forming_rate", "forming rate override"],
  ["custom_forming_qty", "forming quantity override"],
  ["custom_finishing_rate", "finishing rate override"],
  ["custom_finishing_hours", "finishing hours override"],
  ["custom_excavation_hours", "excavation hours override"],
  ["custom_excavation_rate", "excavation rate override"],
];

export function foundationItemInputIssues(item, index = 0) {
  const record = item ?? {};
  const issues = [];
  const add = (field, code, message) => issues.push({
    kind: "foundation", index, componentId: record.component_id ?? null, field, code,
    message: `Foundation ${index + 1}: ${message}`,
  });
  const type = record.foundation_type;
  if (type !== "spread_foot" && type !== "pillar") {
    add("foundation_type", "foundation_type_invalid", "select Spread Footing or Pillar / Caisson.");
  }
  // A recorded excavation method must name a real method — anything else the
  // ported math silently prices on the equipment branch.
  if (record.excavation_method !== undefined && record.excavation_method !== null && record.excavation_method !== ""
    && record.excavation_method !== "hand_dig" && record.excavation_method !== "equipment_excavation") {
    add("excavation_method", "foundation_excavation_method_invalid",
      "select a supported excavation method (Hand dig or Equipment).");
  }
  const count = record.quantity ?? 1;
  const quantity = inputNumber(count);
  if (!positiveWholeNumber(count)) {
    add("quantity", "foundation_quantity_invalid", "quantity must be a positive whole number within the supported range.");
  }
  const fields = type === "spread_foot"
    ? [["length_inches", "length"], ["width_inches", "width"], ["depth_inches", "depth"]]
    : type === "pillar" ? [["diameter", "diameter"], ["depth_inches", "depth"]] : [];
  const dimensions = {};
  for (const [field, label] of fields) {
    const value = inputNumber(record[field]);
    dimensions[field] = value;
    if (value === null || value <= 0) {
      add(field, "foundation_dimension_invalid", `${label} (inches) must be a finite positive number.`);
    }
  }
  if (!issues.length) {
    const depth = dimensions.depth_inches / 12;
    const radius = dimensions.diameter / 24;
    const volume = type === "spread_foot"
      ? ((dimensions.length_inches / 12) * (dimensions.width_inches / 12) * depth) / 27 * quantity
      : (Math.PI * radius * radius * depth) / 27 * quantity;
    // This is numeric-range validation, not a structural design or engineering minimum.
    if (!Number.isFinite(volume) || volume <= 0) {
      add("dimensions", "foundation_volume_out_of_range", "dimensions and quantity cannot produce a finite positive volume in the supported calculation range.");
    }
  }
  if (record.include_rebar) {
    const optional = (field, code, label, valid) => {
      const value = record[field];
      if (value !== undefined && value !== null && !valid(value)) add(field, code, label);
    };
    const positive = value => {
      const number = inputNumber(value);
      return number !== null && number > 0;
    };
    const whole = (field, label) => optional(field, "foundation_rebar_count_invalid",
      `${label} must be a positive whole number within the supported range.`, positiveWholeNumber);
    if (type === "spread_foot") {
      for (const [field, label] of [["rebar_spacing_length", "length"], ["rebar_spacing_width", "width"]]) {
        optional(field, "foundation_rebar_spacing_invalid",
          `rebar spacing ${label} (inches) must be a finite positive number.`, positive);
      }
      whole("rebar_layers", "Rebar mat count");
    } else if (type === "pillar") {
      whole("pillar_rebar_layers", "Hoop count");
      whole("pillar_vertical_rebar_count", "Longitudinal bar count");
      optional("pillar_rebar_hoop_diameter", "foundation_rebar_diameter_invalid",
        "hoop diameter (inches) must be finite, positive and no greater than the foundation diameter.",
        value => positive(value) && (dimensions.diameter === null || dimensions.diameter <= 0 || inputNumber(value) <= dimensions.diameter));
    }
  }
  // Recorded overrides feed the ported cost math verbatim — a malformed or
  // negative override is not a free material. Absent/null means "no override"
  // and skips the check; explicit 0 is a legitimate override value.
  for (const [field, label] of ITEM_CUSTOM_OVERRIDE_FIELDS) {
    const raw = record[field];
    if (raw === undefined || raw === null) continue;
    const number = inputNumber(raw);
    if (number === null || number < 0) {
      add(field, "foundation_override_invalid",
        `${label} must be a finite, nonnegative number — clear it or record a valid value.`);
    }
  }
  return issues;
}

// Signage-cabinet availability — only the two values the ported line math
// (`unit_cost * quantity`) actually consumes are checked; dimensions are
// authored geometry and are never price-consuming.
//
// quantity: absent/blank keeps the ported single-cabinet default. A recorded
// quantity must be finite and positive — a stored 0 bills nothing and the
// ported `|| 1` silently repriced it to one cabinet, so it is held instead of
// guessed. (Fractional positive counts were already billing at face value, so
// they stay valid — never silently repriced.)
//
// unit_cost: must be present, finite and nonnegative. A missing or blank
// price laundered to a $0 "current" amount under `|| 0`; an explicit recorded
// 0 remains a legitimate free cabinet.
const cabinetQuantityNumber = (value) => {
  if (typeof value !== "number" && (typeof value !== "string"
    || !/^[+]?(?:\d+(?:\.\d*)?|\.\d+)(?:e[+-]?\d+)?$/i.test(value.trim()))) return null;
  const number = Number(value);
  return Number.isFinite(number) && number > 0 ? number : null;
};

const cabinetPriceNumber = (value) => {
  if (typeof value !== "number" && (typeof value !== "string"
    || !/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)$/.test(value.trim()))) return null;
  const number = Number(value);
  return Number.isFinite(number) && number >= 0 ? number : null;
};

export function signageCabinetInputIssues(cabinet, index = 0) {
  const issues = [];
  const record = cabinet ?? {};
  const add = (field, code, message) => issues.push({
    kind: "signage_cabinet", index,
    componentId: record.component_id ?? record.id ?? null,
    field, code,
    message: `Signage cabinet ${index + 1}: ${message}`,
  });
  const qty = record.quantity;
  if (qty !== undefined && qty !== null && qty !== "" && cabinetQuantityNumber(qty) === null) {
    add("quantity", "signage_cabinet_quantity_unavailable",
      "record a finite, positive quantity — a zero or malformed quantity cannot be repriced");
  }
  if (cabinetPriceNumber(record.unit_cost) === null) {
    add("unit_cost", "signage_cabinet_price_unavailable",
      "record a finite, nonnegative unit cost — a missing price is not a free cabinet");
  }
  return issues;
}

export function signageCabinetsInputIssues(cabinets = []) {
  return (Array.isArray(cabinets) ? cabinets : [])
    .flatMap((cabinet, index) => signageCabinetInputIssues(cabinet, index));
}

export function foundationProjectInputIssues(project) {
  const items = project?.items ?? [];
  if (!Array.isArray(items)) throw new Error("Foundation items must be an array.");
  // The project default excavation method merges into every item without its
  // own — a recorded value outside the enum silently priced as equipment. The
  // project-level issue names the broken default, and every item inheriting
  // it is held like a recorded-invalid method (its effective method cannot
  // price a real branch).
  const projectIssues = [];
  const method = project?.excavation_method;
  const projectMethodInvalid = method !== undefined && method !== null && method !== ""
    && method !== "hand_dig" && method !== "equipment_excavation";
  if (projectMethodInvalid) {
    projectIssues.push({
      kind: "foundation", index: null, componentId: null,
      field: "excavation_method", code: "foundation_excavation_method_invalid",
      message: "Project: select a supported default excavation method (Hand dig or Equipment).",
    });
  }
  // A recorded landscape design that is not a record (string/number/array)
  // slid past the materials scan as a silent $0 and persisted verbatim — it
  // is unavailable, not free.
  const landscape = project?.landscape;
  const landscapeIssues = landscape !== undefined && landscape !== null
    && (typeof landscape !== "object" || Array.isArray(landscape))
    ? [{
        kind: "landscape", index: null, componentId: null, field: "landscape",
        code: "landscape_unavailable",
        message: "Landscape: the recorded site design is malformed — repair or clear it before repricing.",
      }]
    : landscapeInputIssues(landscape);
  return [
    ...items.flatMap((item, index) => {
      const itemIssues = foundationItemInputIssues(item, index);
      // An item that inherits an invalid project default cannot price a real
      // branch — hold it like a recorded-invalid method.
      if (projectMethodInvalid
        && (item?.excavation_method === undefined || item?.excavation_method === null || item?.excavation_method === "")) {
        itemIssues.push({
          kind: "foundation", index, componentId: item?.component_id ?? null,
          field: "excavation_method", code: "foundation_excavation_method_invalid",
          message: `Foundation ${index + 1}: inherits the invalid project default excavation method — fix the project default or pick a method on this item.`,
        });
      }
      return itemIssues;
    }),
    ...projectIssues,
    ...signageCabinetsInputIssues(project?.signage_cabinets || []),
    ...landscapeIssues,
  ];
}

/**
 * Foundation cost math — ported VERBATIM from SignEstimate Pro
 * (src/pages/NewFoundationEstimate.jsx: getConcreteMixes / getConcreteAdmixtures /
 *  getSmallLoadFee / getFuelSurcharge / calcItemCost / concrete truck totals).
 *
 * Do not "improve" these formulas — they must stay identical to SignEstimate Pro.
 * `settings` is the Settings entity key/value map; `inventory` is FoundationInventory
 * rows plus concrete suppliers normalized out of LaborServiceInventory.
 *
 * Supplier-catalog availability hardening: every catalog price the ready-mix
 * truck math consumes — the selected mix, the selected admixtures, the
 * small-load brackets the trucks fall into, and the per-truck fuel surcharge —
 * must be a recorded finite, nonnegative number. The ported `??` fallbacks
 * guessed retail prices for unpriced suppliers and `settings[key] || def`
 * overrode an explicit 0 rate, so unpriced/invalid catalog values now hold the
 * acknowledged delivery snapshot and are reported instead of laundered into
 * plausible-looking wrong amounts that persist into totals. Only values the
 * ported math actually consumes are checked — an unselected mix, an unneeded
 * small-load bracket, or a zero-yard delivery never triggers a hold.
 */

// Supplier catalog price basis: a recorded finite, nonnegative price — an
// explicit 0 is a legitimate free price. Missing, malformed, negative, or
// non-finite catalog values are unavailable, never guessed.
const supplierPriceNumber = (value) => {
  if (typeof value !== "number" && (typeof value !== "string"
    || !/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)$/.test(value.trim()))) return null;
  const number = Number(value);
  return Number.isFinite(number) && number >= 0 ? number : null;
};

// Settings basis: a missing/blank Settings row keeps the ported module
// default — the same `value === 0 ? 0 : value || fallback` pick the ported
// getSetting applies — while a recorded value must be a finite, nonnegative
// number. An explicit 0 is a legitimate free rate, multiplier, or time for
// every read that only multiplies a cost component — the one read that also
// divides (main labor backing out finishing hours) is flagged positive-only
// at the consumption mirror below. The ported `parseFloat(settings[key] || def)`
// partial-parsed "12abc" to 12 and returned NaN for "abc", and the `num()`
// rollups then laundered NaN into finite-wrong persisted totals — a malformed
// recorded setting now reports and holds the item instead.
const foundationSettingNumber = (value, fallback) =>
  supplierPriceNumber(value === 0 ? 0 : value || fallback);

// Settings the ported calcItemCost consumes, mirrored key-by-key — only the
// keys an item's recorded configuration actually reads are checked, each with
// the ported getSetting fallback and a label for the diagnostic. The caller
// mirrors this on the same effective item the ported math runs against (the
// project default excavation method already merged). `positive` marks a read
// where the ported math divides by the setting — an explicit 0 there is not a
// legitimate "free" rate, it is Infinity/NaN laundered downstream.
const itemSettingConsumption = (item) => {
  const has = (v) => v !== undefined && v !== null;
  // Pouring cost is always `volumeCY * pouring_cost_per_cy`.
  const consumed = [["foundation_pouring_cost_per_cy", 15, "pouring labor cost per CY"]];
  // Main labor defaults the excavation and finishing rates and backs out
  // finishing hours — an explicit custom rate/hours covers that path instead.
  // With finishing enabled and no custom finishing hours, the ported math
  // divides `defaultFinishingCost / main_labor_rate` — a 0 rate must be a
  // positive read there.
  const laborDivides = Boolean(item?.include_finishing) && !has(item?.custom_finishing_hours);
  if (!has(item?.custom_excavation_rate)
    || item?.include_rebar
    || (item?.include_finishing && (!has(item?.custom_finishing_rate) || !has(item?.custom_finishing_hours)))) {
    consumed.push(["foundation_main_labor_rate", 60, laborDivides ? "positive main labor rate" : "main labor rate", laborDivides]);
  }
  if (item?.include_rebar) {
    consumed.push(
      ["foundation_rebar_time_cross_section", 0.05, "rebar time per intersection"],
      ["foundation_rebar_time_linear_ft", 0.02, "rebar time per linear foot"],
    );
  }
  if (item?.include_forming) {
    consumed.push(
      ["foundation_forming_cost_per_sqft", 2.5, "forming labor cost per sq ft"],
      item?.foundation_type === "spread_foot"
        ? ["foundation_forming_materials_spread_foot", 0.5, "spread-foot forming materials multiplier"]
        : ["foundation_forming_materials_pillar", 0.75, "pillar forming materials multiplier"],
    );
  }
  if (item?.include_finishing && !has(item?.custom_finishing_hours)) {
    consumed.push(["foundation_finishing_cost_per_sqft", 1.25, "finishing labor cost per sq ft"]);
  }
  if (!has(item?.custom_excavation_hours)) {
    consumed.push(
      item?.excavation_method === "hand_dig" || !item?.excavation_method
        ? ["foundation_hand_dig_time_per_cy", 2.0, "hand excavation time per CY"]
        : ["foundation_equipment_excavation_time_per_cy", 0.5, "equipment excavation time per CY"],
    );
  }
  return consumed;
};

// A consumed Settings value the ported math cannot parse is not a guessed
// rate — the item is reported and held, the same contract as the wall/pole
// setting checks (wall_setting_unavailable / pole_paint_setting_unavailable).
export const foundationItemSettingIssues = (item, settings = {}, index = 0) => {
  const issues = [];
  for (const [key, fallback, label, positive] of itemSettingConsumption(item)) {
    const number = foundationSettingNumber(settings?.[key], fallback);
    if (number === null || (positive && number <= 0)) {
      issues.push({
        kind: "foundation", index, componentId: item?.component_id ?? null,
        field: key, inventoryId: null, code: "foundation_setting_unavailable",
        message: `Foundation ${index + 1}: record a finite, ${positive ? "positive" : "nonnegative"} ${label.replace(/^positive /, "")} in Estimator Settings before repricing.`,
      });
    }
  }
  return issues;
};

// Catalog price reads normalize on this calculation copy only — authored
// inventory rows are never mutated. A null price means "not cataloged"; the
// `field` key names the supplier column a diagnostic points at.
export const getConcreteMixes = (invItem) => [
  { id: '3500_ae', name: '3500 AIR ENTRAINED (AE)', price: supplierPriceNumber(invItem?.mix_3500_price), field: 'mix_3500_price', desc: 'Often used for driveways, slabs, and moderate-load footings.' },
  { id: '4000_ae', name: '4000 AIR ENTRAINED (AE)', price: supplierPriceNumber(invItem?.mix_4000_price), field: 'mix_4000_price', desc: 'STANDARD. Used for sign foundations, commercial flatwork, and structural footings requiring good durability.' },
  { id: '4500_ae', name: '4500 AIR ENTRAINED (AE)', price: supplierPriceNumber(invItem?.mix_4500_price), field: 'mix_4500_price', desc: 'Used for heavy-duty commercial slabs and heavy traffic areas.' },
  { id: '5000_ae', name: '5000 AIR ENTRAINED (AE)', price: supplierPriceNumber(invItem?.mix_5000_price), field: 'mix_5000_price', desc: 'High-strength mix for heavy structural columns, pillars, and extreme load conditions.' },
  { id: 'fast_set', name: 'FAST SET', price: supplierPriceNumber(invItem?.mix_fast_set_price), field: 'mix_fast_set_price', desc: 'Quick-curing concrete used when rapid strength gain is needed to minimize downtime.' },
];

export const getConcreteAdmixtures = (invItem) => [
  { id: 'calcium_chloride', name: 'Calcium Chloride', price: supplierPriceNumber(invItem?.admix_calcium_chloride_price), field: 'admix_calcium_chloride_price', desc: 'Speeds up how fast the concrete dries. SELECT THIS when pouring in cold weather so it doesn\'t freeze before it sets. WARNING: Do NOT select this if using Rebar, as it causes rust!' },
  { id: 'set_retarding', name: 'Set-Retarding Admix (Type D)', price: supplierPriceNumber(invItem?.admix_set_retarding_price), field: 'admix_set_retarding_price', desc: 'Slows down how fast the concrete dries. SELECT THIS when pouring in very hot weather, or if the concrete truck has a very long drive to the site.' },
  { id: 'water_reducing', name: 'Water-Reducing Admix (Type A)', price: supplierPriceNumber(invItem?.admix_water_reducing_price), field: 'admix_water_reducing_price', desc: 'Makes the concrete easier to pour without weakening it. SELECT THIS if you need the concrete to flow better into tight forms or around lots of rebar.' },
  { id: 'fibers', name: 'Fibers', price: supplierPriceNumber(invItem?.admix_fibers_price), field: 'admix_fibers_price', desc: 'Tiny fibers mixed into the concrete to prevent small cracks. SELECT THIS for large flat slabs (like monument sign pads) or if the foundation will take physical abuse.' },
  { id: 'winter_service', name: 'Winter Service', price: supplierPriceNumber(invItem?.admix_winter_service_price), field: 'admix_winter_service_price', desc: 'A fee the plant charges to use hot water so the mix doesn\'t freeze. SELECT THIS always during winter months when temperatures are freezing.' },
];

// Get the small load fee for a given number of yards based on supplier bracket pricing.
// >= 5 yards has no fee by formula; smaller brackets return null when the
// supplier has not cataloged a fee for the consumed bracket.
export const getSmallLoadFee = (yards, invItem) => {
  if (yards >= 5) return 0;
  if (yards >= 4.5) return supplierPriceNumber(invItem?.small_load_fee_4_5_4_75);
  if (yards >= 4) return supplierPriceNumber(invItem?.small_load_fee_4_4_25);
  if (yards >= 3) return supplierPriceNumber(invItem?.small_load_fee_3_3_75);
  if (yards >= 2) return supplierPriceNumber(invItem?.small_load_fee_2_2_75);
  if (yards >= 1) return supplierPriceNumber(invItem?.small_load_fee_1_1_75);
  return supplierPriceNumber(invItem?.small_load_fee_1_1_75); // under 1 yd still gets the smallest bracket fee
};

export const getFuelSurcharge = (invItem) => {
  return supplierPriceNumber(invItem?.fuel_surcharge);
};

