          {mixMissing && <option value={savedMixId} disabled>Catalog mix unavailable ({savedMixId})</option>}
          {mixes.map((m) => (
            <option key={m.id} value={m.id}>
              {m.name} — {hasFoundationCostSnapshot(m.price) ? `${money(m.price)}/CY` : "price unavailable"}
